def transform(grid):
    h, w = len(grid), len(grid[0])

    # The most frequent color is the background.
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    bg = max(counts, key=counts.get)

    # Locate the full-length divider.
    divider = None
    for r, row in enumerate(grid):
        if row[0] != bg and all(value == row[0] for value in row):
            divider = ("h", r)
            break
    if divider is None:
        for c in range(w):
            if grid[0][c] != bg and all(grid[r][c] == grid[0][c] for r in range(h)):
                divider = ("v", c)
                break
    if divider is None:
        return [row[:] for row in grid]

    orient, pos = divider
    obj = [
        (r, c, grid[r][c])
        for r in range(h)
        for c in range(w)
        if grid[r][c] != bg and (r != pos if orient == "h" else c != pos)
    ]
    if not obj:
        return [row[:] for row in grid]

    out = [row[:] for row in grid]

    if orient == "h":
        lo = min(r for r, _, _ in obj)
        hi = max(r for r, _, _ in obj)
        shift = (pos + 1 - lo) if lo > pos else (pos - 1 - hi)
        for r, c, _ in obj:
            out[r][c] = bg
        for r, c, color in obj:
            out[r + shift][c] = color
        stripe = (hi + shift + 1) if lo > pos else (lo + shift - 1)
        if 0 <= stripe < h:
            out[stripe] = [8] * w
    else:
        lo = min(c for _, c, _ in obj)
        hi = max(c for _, c, _ in obj)
        shift = (pos + 1 - lo) if lo > pos else (pos - 1 - hi)
        for r, c, _ in obj:
            out[r][c] = bg
        for r, c, color in obj:
            out[r][c + shift] = color
        stripe = (hi + shift + 1) if lo > pos else (lo + shift - 1)
        if 0 <= stripe < w:
            for r in range(h):
                out[r][stripe] = 8

    return out
